public class AssetBundleSceneLoader :
MonoBehaviour
{
AssetBundle
sceneBundle = null;
bool sceneLoaded = false;
// Triggered when the scene containing this
MonoBehaviour
is loaded
void Start()
{
StartCoroutine(LoadAssetBundleAndScene());
StartCoroutine(CleanupAfterDelay());
}
IEnumerator LoadAssetBundleAndScene()
{
// Determine the path to the
AssetBundle
.
//
Application.streamingAssetsPath
is used so that this works in both the Player and Play mode in the
Editor
.
string AssetBundleBuildPath =
Application.streamingAssetsPath
+ Constants.AssetBundlePath;
var bundlePath = AssetBundleBuildPath + "/" + Constants.AssetBundleFileName;
var op =
AssetBundle.LoadFromFileAsync
(bundlePath);
yield return op;
sceneBundle = op.assetBundle;
if (sceneBundle == null)
{
Debug.LogError
("Failed to load
AssetBundle
: " + Constants.AssetBundleFileName);
}
else
{
var sceneLoadOp =
SceneManager.LoadSceneAsync
(Constants.SceneForAssetBundle,
LoadSceneMode.Additive
);
if (sceneLoadOp == null)
Debug.Log
($"Failed to load {Constants.SceneForAssetBundle}");
else
{
yield return sceneLoadOp;
Scene
sceneLookup =
SceneManager.GetSceneByPath
(Constants.SceneForAssetBundle);
//Will report "Finished loading SceneForBundle (index -1)."
Debug.Log
($"Finished loading {sceneLookup.name} (index {sceneLookup.buildIndex}).");
sceneLoaded = true;
}
}
}
IEnumerator CleanupAfterDelay()
{
yield return new
WaitForSeconds
(3.0f);
if (sceneLoaded)
yield return
SceneManager.UnloadSceneAsync
(Constants.SceneForAssetBundle);
sceneLoaded = false;
if (sceneBundle != null)
yield return sceneBundle.UnloadAsync(true);
sceneBundle = null;
Debug.Log
("Finished unloading Content");
}
}
